The issue arises because your `AuthGuard` service does not have access to the `OktaAuthStateService`. To resolve this, ensure that `OktaAuthStateService` is properly provided in your module's providers array. Here’s how you can adjust your code:

1. Ensure `OktaAuthModule` and `OktaAuthStateService` are imported correctly.
2. Provide `OktaAuthStateService` in the `providers` array of `AppModule`.

Here is a concise adjustment to your `app.module.ts`:

```ts
import { NgModule } from '@angular/core';
import { AppComponent } from './app.component';
import { OktaAuthModule, OKTA_CONFIG } from '@okta/okta-angular';
import { OktaAuth } from '@okta/okta-auth-js';
import myAppConfig from './app.config';
const oktaConfig = myAppConfig.oidc;
const oktaAuth = new OktaAuth(oktaConfig);

@NgModule({
  declarations: [AppComponent],
  imports: [OktaAuthModule],
  providers: [
    { provide: OKTA_CONFIG, useValue: { oktaAuth } },
    // Ensure OktaAuthStateService is provided
    OktaAuthStateService,
  ],
  bootstrap: [AppComponent]
})
export class AppModule {}
```

Additionally, ensure your `AuthGuard` service imports and uses `OktaAuthStateService` correctly:

```ts
import { Injectable } from '@angular/core';
import { Router, UrlTree } from '@angular/router';
import { OktaAuthStateService } from '@okta/okta-angular';

@Injectable({ providedIn: 'root' })
export class AuthGuard {
  constructor(
    private authStateService: OktaAuthStateService,
    private router: Router
  ) {}

  canActivate(): boolean {
    return this.authStateService.authState$.pipe(
      map((loggedIn) => {
        console.log('loggedIn', loggedIn);
        if (!loggedIn) {
          this.router.navigate(['/login']);
          return false;
        }
        return true;
      })
    ).toPromise();
  }
}
```

This setup ensures that `AuthGuard` has access to the necessary services, resolving the `NullInjectorError`.

