```typescript
import { Component, ViewChild, afterNextRender } from '@angular/core';
import ApexCharts from 'apexcharts';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html'
})
export class DashboardComponent {
  @ViewChild('chart') chart!: ElementRef;

  constructor() {
    // Use `afterNextRender` to ensure the chart is initialized only on the client side
    afterNextRender(() => {
      const element = this.chart.nativeElement;
      new ApexCharts(element, {
        series: [
          { name: 'STOCK ABC', data: [/* your data */] }
        ],
        // other chart options...
      }).render();
    });
  }

  ngOnInit(): void {}
}
```

This approach leverages `afterNextRender` to delay the initialization of ApexCharts until after Angular has finished rendering, ensuring that browser-specific APIs like `window` are available. This way, your application will work seamlessly in both SSR and client-side environments.

