The issue you're encountering stems from how Angular handles validation and change detection in reactive forms compared to template-driven forms. When pasting values, the `input` event might not trigger the same way as typing does, leading validators to not run immediately after formatting.

To address this, ensure your custom directive also triggers a form control update when formatting happens:

1. **Update Your Directive**:
   Ensure that after formatting, you manually set the value of the form control using `patchValue` or `setValue`.

2. **Typescript Code Update**:
   ```typescript
   import { Directive, HostListener, ElementRef } from '@angular/core';
   import { FormControl } from '@angular/forms';

   @Directive({
     selector: '[phoneFormatterDirective]'
   })
   export class PhoneFormatterDirective {
     constructor(private elementRef: ElementRef) {}

     @HostListener('input', ['$event'])
     onKeyDown(event: KeyboardEvent) {
       event.preventDefault();
       const input = this.elementRef.nativeElement as HTMLInputElement;
       let trimmed = input.value
         .replaceAll('-', '')
         .replaceAll('(', '')
         .replaceAll(')', '')
         .replaceAll(/\s+/g, '');

       if (trimmed.length > 12) {
         trimmed = trimmed.substr(0, 12);
       }
       let numbers = [];
       numbers.push(trimmed.substr(0, 3));
       if (trimmed.substr(3, 2)!=="") {
         numbers.push(trimmed.substr(3, 3));
       }
       if (trimmed.substr(6, 3)!="") {
         numbers.push(trimmed.substr(6, 4));
       }

       input.value = numbers.join('-');

       // Update the form control value
       const phoneControl: FormControl = this.elementRef.nativeElement.formControl;
       if (phoneControl) {
         phoneControl.patchValue(numbers.join('-'));
       }
     }
   }
   ```

3. **FormControl Setup**:
   Ensure your `FormControl` is correctly set up with the validator:

   ```typescript
   phone: new FormControl(null, [Validators.pattern('^[0-9]{3}-[0-9]{3}-[0-9]{4}$')])
   ```

This approach ensures that the form control's value and validation state are updated consistently when pasting or formatting values.

