Here’s how you can structure your template:

```angular-ts
@Component({
  ...
  template: `
    @if (licenseOverview.orders.length > 0) {
      <table>
        <thead>
          <tr>
            <th>{{ 'Order' }}</th>
            <th>{{ 'Expected On' }}</th>
            <th>{{ 'Status' }}</th>
          </tr>
        </thead>
        <tbody>
          @for (order of licenseOverview.orders; track order.id) {
            <tr>
              <td>{{ order.reference }}</td>
              <td>{{ order.expectedOn }}</td>
              <td>{{ order.status }}</td>
            </tr>
          }
        </tbody>
      </table>
    } 
    @empty { No data for you! }
  `,
})
