To ensure `VistaFacturasComponent` calls `filterFacturas()` whenever `searchBarService.searchTextSignal` updates, you can use Angular's signal and the `async` pipe to reactively update your component. Here’s how:

1. Import necessary signals:
   ```typescript
   import { Component } from '@angular/core';
   import { signal } from '@angular/core';
   ```

2. Use the `searchTextSignal` in your template with the `async` pipe and combine it with `@if` to call `filterFacturas()` only when there's a new value:
   ```typescript
   @Component({
     selector: 'vista-facturas',
     templateUrl: './vista-facturas.component.html',
     styleUrls: ['./vista-facturas.component.css']
   })
   export class VistaFacturasComponent {
     filteredFacturasArray = signal([]);

     constructor(private facturaService: FacturaService, public searchBarService: SearchBarService) { }

     getFacturas(): void {
       this.facturaService.getFacturas().subscribe(facturasReturned => 
         this.filteredFacturasArray.set(facturasReturned));
     }

     filterFacturas(text: string): void {
       if (!text) {
         this.filteredFacturasArray.set(this.facturasArray);
       } else {
         this.filteredFacturasArray.set(
           this.facturasArray.filter(factura => factura?.numero.toString().includes(text))
         );
       }
     }

     ngOnInit(): void {
       this.getFacturas();
     }
   }
   ```

3. Update your template to use the `async` pipe and call `filterFacturas()`:
   ```html
   <div *ngIf="searchBarService.searchTextSignal() as text">
     <button (click)="filterFacturas(text)">Filter</button>
   </div>
   ```

4. Ensure your template uses the filtered array for rendering items:
   ```html
   <div *ngFor="let factura of filteredFacturasArray()">
     <!-- Display factura details -->
   </div>
   ```

By using signals and the `async` pipe, you can reactively update the component whenever `searchBarService.searchTextSignal` changes.

