The issue lies in how you're using `inject` outside of an injection context. In your guard function, you are trying to use `UserService` and `Router`, which should be provided within the module's providers array or via a factory function. Since these services aren't properly provided, Angular cannot resolve them.

To fix this, ensure that `UserService` is declared as a provider in your module:

```typescript
import { NgModule } from '@angular/core';
import { RouterModule } from '@angular/router';

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  providers: [UserService], // Ensure UserService is provided here
  exports: [RouterModule]
})
export class AppRoutingModule {}
```

Alternatively, you can use a factory function to provide the guard:

```typescript
import { CanActivateFn, Router } from '@angular/router';
import { inject } from '@angular/core';
import { UserService } from '../users/user.service';

export const authGuard: CanActivateFn = (route, state) => {
  return createAuthGuard(route, state);
};

function createAuthGuard(route: ActivatedRouteSnapshot, state: RouterStateSnapshot): boolean | void {
  const userService = inject(UserService);
  const router = inject(Router);

  if (!userService.is_authenticated()) {
    router.navigate(['login', state.url]);
    return false;
  }
  return true;
}
```

This approach ensures that `UserService` is properly provided and can be injected within the guard function.

