     declarations: [Module2Component, Module2DetailsComponent],
     imports: [RouterModule.forChild(routes), ThirdModule],
     exports: [RouterModule]
   })
   export class SecondModule {}
   ```

By using `forChild` in lazy-loaded modules and ensuring `RouterModule` is only provided at the root level via `forRoot`, you avoid the error and ensure proper lazy loading.

