    @isset($subcopy)
        {{ $subcopy }}
    @endisset

    <div>
        Unsubscribe here: <a href="{{ $unsubscribe_url }}">Unsubscribe</a>
    </div>

@endsection
```

This approach ensures that your customizations are properly integrated with the vendor template.

