The issue you're encountering likely stems from how Angular handles route changes and guards during page reloads. When you navigate using `router.navigate`, it can cause a brief render of the target component, including your login component, before the guard logic fully executes.

To address this, ensure that your guard properly handles navigation without causing an immediate render by returning a promise or observable from your guard function. Here's how you can adjust your `AuthGuard`:

```typescript
import { CanActivateFn, Router } from '@angular/router';
import { TokenService } from './token.service';

export const authGuard: CanActivateFn = (route, state) => {
  const tokenService = inject(TokenService);
  const router = inject(Router);

  return tokenService.isAuthentications.pipe(
    map((user) => {
      if (!user) {
        return router.createUrlTree(['/login']);
      }
      return true;
    })
  );
};
```

This approach ensures that the navigation only occurs after the guard logic has fully executed, preventing the brief render of the login component.

Additionally, ensure your `TokenService` correctly handles token persistence and authentication status updates. The `BehaviorSubject` should be updated immediately when a token is set or removed:

```typescript
import { BehaviorSubject } from 'rxjs';

export class TokenService {
  isAuthentications = new BehaviorSubject<boolean>(false);

  constructor(@Inject(PLATFORM_ID) private platformId: Object) {
    const token = this.getToken();
    if (token) {
      this.updateToken(true);
    }
  }

  setToken(token: string) {
    this.updateToken(true);
    localStorage.setItem('user', token);
  }

  updateToken(status: boolean) {
    this.isAuthentications.next(status);
  }

  getToken(): string | null {
    if (typeof window !== 'undefined' && window.sessionStorage) {
      return localStorage.getItem('user');
    }
    return null;
  }
}
```

This setup should help mitigate the issue of the login component briefly rendering during page reloads.

