// app/Models/Hangszer.php
public function tipusok()
{
    return $this->belongsToMany(InstrumentType::class)->withPivot('t_id');
}

// app/Models/InstrumentType.php
public function hangszerek()
{
    return $this->belongsToMany(Hangszer::class);
}
```

Next, create a resource for `Hangszer`:

```php
// app/Http/Resources/HangszerResource.php
namespace App\Http\Resources;

use Illuminate\Http\Resources\Json\ResourceCollection;

class HangszerResource extends ResourceCollection
{
    public function toArray($request)
    {
        return [
            'h_id' => $this->id,
            'hangszer_nev' => $this->name,
            'brutto_ar' => $this->price,
            'kep_url' => $this->image_url,
            'cikkszam' => $this->code,
            'leiras' => $this->description,
            'tipusok' => InstrumentTypeResource::collection($this->whenLoaded('tipusok')),
        ];
    }
}
```

And a resource for `InstrumentType`:

```php
// app/Http/Resources/InstrumentTypeResource.php
namespace App\Http\Resources;

