To ensure `VistaFacturasComponent` reacts to changes in `searchBarService.searchTextSignal`, you can use Angular's signals and effects to track the signal updates. Here’s how:

1. Import necessary utilities:
```typescript
import { Component, OnInit } from '@angular/core';
import { signal } from '@angular/core/signals';
import { toObservable } from '@angular/core/rxjs-interop';
```

2. Use `toObservable` and an effect in your component to listen for changes:

```typescript
@Component({
  selector: 'vista-facturas',
  templateUrl: './vista-facturas.component.html',
  styleUrls: ['./vista-facturas.component.css']
})
export class VistaFacturasComponent implements OnInit {
  filteredFacturasArray = signal([]);

  constructor(private searchBarService: SearchBarService) {}

  ngOnInit(): void {
    this.getFacturas();

    // Listen for changes in searchTextSignal
    toObservable(this.searchBarService.searchTextSignal)
      .pipe(
        tap(text => this.filterFacturas())
      )
      .subscribe();
  }

  getFacturas(): void {
    // Initialize arrays as before.
  }

  filterFacturas(): void {
    let text = this.searchBarService.searchTextSignal();

    if (!text) 
      this.filteredFacturasArray.set(this.facturasArray);

    this.filteredFacturasArray.set(
      this.facturasArray.filter(factura => factura?.numero.toString().includes(text))
    );
  }
}
```

This setup ensures that `filterFacturas` is called whenever the `searchTextSignal` updates, keeping your filtered array in sync with the search input.

