To address the issue of showing a loading status during lazy-loaded route transitions in your Angular application, you can implement a global loader or spinner component that gets displayed while the routes and components are being loaded. This approach ensures that users see a more pleasant user experience instead of an unstyled or incorrect UI.

First, create a `loading.component` to display the loading state:

```typescript
// loading.component.ts
import { Component } from '@angular/core';

@Component({
  selector: 'app-loading',
  template: `<div>Loading...</div>`
})
export class LoadingComponent {}
```

Then, update your routing configuration to include this component during lazy loading transitions. You can use a `canActivate` guard in the `appAuthorizedRoutes` to show the loader:

```typescript
// app-authorized.routes.ts
import { NgModule } from '@angular/core';
import { RouterModule, Routes, CanLoad } from '@angular/router';

const routes: Routes = [
  {
    path: 'dashboard',
    component: DashboardComponent,
    canActivate: [AuthGuard],
    title: 'Dashboard'
  },
  {
    path: 'settings',
    component: SettingsComponent,
    canActivate: [AuthGuard],
    title: 'Settings'
  },
  // etc...
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class AppAuthorizedRoutingModule {}

// app.routes.ts
import { RouterModule, Routes } from '@angular/router';
import { CanLoadGuard } from './can-load.guard';

const appRoutes: Routes = [
  {
    path: '',
    redirectTo: '/dashboard',
    pathMatch: 'full'
  },
  {
    path: 'login',
    component: LoginComponent,
    title: 'Login'
  },
  {
    path: '',
    canActivateChild: [AuthGuard],
    loadChildren: () => import(`./app-authorized.routes`).then(m => m.AppAuthorizedRoutingModule),
    canLoad: [CanLoadGuard] // Use the CanLoad guard to show loader
  },
  { path: '**', redirectTo: '/dashboard' }
];

export const routes = RouterModule.forRoot(appRoutes);
```

Implement the `CanLoadGuard`:

```typescript
// can-load.guard.ts
import { Injectable } from '@angular/core';
import { CanLoad, Route, UrlSegment, Router } from '@angular/router';

@Injectable({
  providedIn: 'root'
})
export class CanLoadGuard implements CanLoad {
  constructor(private router: Router) {}

  canLoad(route: Route): boolean | Promise<boolean>

