To ensure both main and thumb Swipers initialize correctly without reinitializing twice, you can run their initialization outside of the Angular zone using `NgZone`. Here’s how to do it:

1. Import necessary modules and services.
2. Use `NgZone.runOutsideAngular` for initializing Swiper components.

```typescript
import { Component, OnInit, ViewChild, ElementRef, NgZone } from '@angular/core';
// import Swiper core and required modules
import * as Swiper from 'swiper';

@Component({
  selector: 'app-swiper-thumbs-vertical-dup-1',
  templateUrl: './swiper-thumbs-vertical-dup-1.component.html'
})
export class SwiperThumbsVerticalDup1Component implements OnInit {
  @ViewChild('swiper1') swiper1!: ElementRef;
  @ViewChild('swiper2') swiper2!: ElementRef;

  constructor(private zone: NgZone) {}

  ngOnInit() {
    this.zone.runOutsideAngular(() => {
      const swiperParams = {
        // main Swiper parameters
      };
      const swiperParams1 = {
        spaceBetween: 10,
        // thumb Swiper parameters
      };

      Object.assign(this.swiper2.nativeElement, swiperParams1);
      new Swiper(this.swiper2.nativeElement);

      Object.assign(this.swiper1.nativeElement, swiperParams);
      new Swiper(this.swiper1.nativeElement);
    });
  }
}
```

This approach ensures that both Swipers are initialized only once when the component is loaded or route changes, avoiding unnecessary reinitializations.

