    return [$item['barcode'], $item['location']];
});

$result = $grouped->map(function ($group, $key) {
    list($barcode, $location) = $key;
    return [
        'id' => $group->first()['id'],
        'barcode' => $barcode,
        'description' => $group->first()['description'],
        'quantity' => $group->sum('quantity'),
        'location' => $location
    ];
})->values();

