For lazy-loaded modules or when migrating from class-based guards, explicitly provide `UserService` in your module's `providers` array:

```typescript
import { NgModule } from '@angular/core';
import { RouterModule } from '@angular/router';
import { UserService } from './users/user.service';

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule],
  providers: [UserService] // Ensure UserService is provided here
})
export class AppModule {}
```

Alternatively, if `UserService` should be a singleton across the entire application:

```typescript
import { NgModule } from '@angular/core';
import { RouterModule } from '@angular/router';
import { UserService } from './users/user.service';

@NgModule({
  imports: [RouterModule.forRoot(routes)],
  exports: [RouterModule],
  providers: [UserService] // Use providedIn: 'root' in @Injectable decorator if not provided here
})
export class AppModule {}
```

This ensures `UserService` is available for injection throughout your application, resolving the `NullInjectorError`.

