The error "localStorage is not defined" occurs because `localStorage` is a browser API and isn't available in non-browser environments like Node.js, which might be used during testing or building your Angular application with tools like Webpack.

To resolve this issue, you can use the `window` object to check if `localStorage` is available before using it. Here's how you can modify your AuthService:

```typescript
import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  public isAuth = new BehaviorSubject(false);

  constructor(private router: Router) {
    this.autoSignIn();
  }

  autoSignIn() {
    if (window && window.localStorage.getItem('email')) {
      this.isAuth.next(true);
      this.router.navigate(['/dashboard']);
    }
  }

  signIn(email: string) {
    if (window && window.localStorage) {
      window.localStorage.setItem('email', email);
    }
    this.isAuth.next(true);
    this.router.navigate(['/dashboard']);
  }

  signOut() {
    if (window && window.localStorage) {
      window.localStorage.removeItem('email');
    }
    this.isAuth.next(false);
    this.router.navigate(['/auth']);
  }
}
```

By adding the `window` check, you ensure that your service only attempts to use `localStorage` when it's available in a browser environment.

