In Angular 17, you can use `@if` and `@else` to conditionally render parts of your template without combining them into a single `*ngIf`. Your goal is to show different content based on the length of the `movies` array. Here’s how you can achieve this:

```angular-ts
@Component({
  selector: 'app-movie-list',
  template: `
    @if (movies) {
      @if (movies.length > 0) {
        Favorites 
        <div>
          Recent 
          {{ movies[movies.length - 1].title }}
          -
          {{ movies[movies.length - 1].rating }}
        </div>
        Total 
        {{ movies.length }} 
      } @else {
        Favorites 
        <div>
          Recent 
          NA
        </div>
        Total 
        0 
      }
    }
  `,
})
export class MovieListComponent {
  movies: any[] = []; // Initialize your array as needed.
}
