The error `NullInjectorError: No provider for OktaAuthStateService` indicates that Angular cannot find a provider for this service in your module's providers array. To resolve this, ensure you import and provide the `OktaAuthStateService` correctly.

In your `app.module.ts`, add the `OktaAuthStateService` to the providers array:

```typescript
import { OktaAuthStateService } from '@okta/okta-angular';

@NgModule({
  // ...
  providers: [
    { provide: OKTA_CONFIG, useValue: { oktaAuth } },
    OktaAuthStateService, // Add this line
  ],
  // ...
})
export class AppModule {}
```

Additionally, ensure your `AuthGuard` is correctly set up to handle the `authState$` observable:

```typescript
import { Injectable } from '@angular/core';
import { Router, UrlTree } from '@angular/router';
import { OktaAuthStateService } from '@okta/okta-angular';

@Injectable({ providedIn: 'root' })
export class AuthGuard {
  constructor(
    private authStateService: OktaAuthStateService,
    private router: Router
  ) {}

  canActivate(): boolean {
    return this.authStateService.authState$.pipe(
      map((loggedIn) => {
        if (!loggedIn) {
          this.router.navigate(['/login']);
          return false;
        }
        return true;
      })
    ).toPromise();
  }
}
```

Make sure to import `OktaAuthStateService` in your `AuthGuard` and use `.toPromise()` instead of `Observable` for simplicity.

