To solve your problem, you need to use signals effectively and ensure that `VistaFacturasComponent` reacts to changes in `searchTextSignal`. Here's how:

1. Convert `filteredFacturasArray` to a signal.
2. Use the `toObservable` utility from excerpt [3] to create an observable from `searchTextSignal`.
3. Subscribe to this observable and call `filterFacturas()` whenever the text changes.

Here’s a simplified version of your component:

```typescript
import { Component, signal } from '@angular/core';
import { toObservable } from '@angular/core/rxjs-interop'; // Import rxjs-interop for toObservable

@Component({
  selector: 'vista-facturas',
  templateUrl: './vista-facturas.component.html',
  styleUrls: ['./vista-facturas.component.css']
})
export class VistaFacturasComponent {

  filteredFacturasArray = signal([]); // Convert to a signal
  searchText$ = toObservable(this.searchBarService.searchTextSignal()); // Create an observable

  constructor(private facturaService: FacturaService, public searchBarService: SearchBarService) { }

  getFacturas(): void {
    this.facturaService.getFacturas().subscribe(facturasReturned => 
      this.filteredFacturasArray.set(facturasReturned));
  }

  filterFacturas(text: string): void {
    if (!text) {
      this.filteredFacturasArray.set(this.facturasArray);
    } else {
      const filtered = this.facturasArray.filter(factura => factura?.numero.toString().includes(text));
      this.filteredFacturasArray.set(filtered);
    }
  }

  ngOnInit(): void {
    this.getFacturas();
    // Subscribe to searchTextSignal changes
    this.searchText$.subscribe(this.filterFacturas.bind(this));
  }
}
```

This setup ensures that `filterFacturas` is called whenever the search text changes, updating `filteredFacturasArray` accordingly.

