The issue you're encountering likely stems from how Angular handles route changes and guards during page reloads. When you navigate using `router.navigate`, it doesn't always guarantee that the guard will run before rendering the component, especially on initial load or when navigating back to a protected route.

To address this, ensure your `AuthGuard` properly checks for authentication status without relying solely on navigation. Here's an improved version of your `AuthGuard`:

```typescript
export const authGuard: CanActivateFn = (route, state) => {
  const tokenService = inject(TokenService);
  return tokenService.isAuthentications.pipe(
    map((user) => {
      if (!user) {
        // Prevent rendering the dashboard by returning false.
        return false;
      }
      return true;
    }),
    catchError(() => of(false)) // Handle any errors by redirecting to login
  );
};
```

In your `TokenService`, ensure it correctly handles authentication status:

```typescript
export class TokenService {
  isAuthentications = new BehaviorSubject<boolean>(false);

  constructor(@Inject(PLATFORM_ID) private platformId: Object) { 
    const token = this.getToken();
    if (token) {
      this.updateToken(true);
    }
  }

  setToken(token: string) {
    this.updateToken(true);
    localStorage.setItem('user', token);
  }

  updateToken(status: boolean) {
    this.isAuthentications.next(status);
  }

  getToken(): string | null {
    if (typeof window !== 'undefined' && window.sessionStorage) {
      return localStorage.getItem('user');
    }
    return null;
  }
}
```

Ensure your routes are correctly configured to handle redirections:

```typescript
export const routes: Routes = [
  { path: 'login', component: LoginComponent },
  { path: '', redirectTo: '/login', pathMatch: 'full' },
  {
    path: '',
    component: LayoutComponent,
    children: [
      { path: 'dashboard', component: DashboardComponent, canActivate: [authGuard] }
    ]
  }
];
```

This setup ensures that the guard runs before rendering any components, preventing the brief display of the login page.

